// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IFlashLoanProvider {
    function flashLoan(address receiver, address token, uint256 amount, bytes calldata data) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/// @title MonitoringAgent - Logs flash loan activity through reverse proxy
/// @notice This contract acts as a monitoring layer that logs and validates
///         flash loan transactions before forwarding them to the actual provider
contract MonitoringAgent is Ownable, ReentrancyGuard {

    struct LoanRecord {
        address borrower;
        address token;
        uint256 amount;
        uint256 timestamp;
        bytes32 txHash;
        bool settled;
    }

    mapping(bytes32 => LoanRecord) public loanRecords;
    mapping(address => uint256) public borrowerNonces;
    mapping(address => bool) public approvedProviders;
    mapping(address => uint256) public providerLiquidity;

    uint256 public constant MAX_LOAN_RATIO = 95; // 95% of available liquidity
    uint256 public totalLoansIssued;
    uint256 public activeLoans;

    address public immutable proxyRelayer;

    event LoanRequested(bytes32 indexed loanId, address indexed borrower, uint256 amount);
    event LoanSettled(bytes32 indexed loanId, bool success);
    event ProviderRegistered(address indexed provider);
    event LiquidityUpdated(address indexed provider, uint256 newAmount);

    modifier onlyProxy() {
        require(msg.sender == proxyRelayer || msg.sender == owner(), "Not authorized");
        _;
    }

    modifier validProvider(address provider) {
        require(approvedProviders[provider], "Provider not approved");
        _;
    }

    constructor(address _proxyRelayer) {
        proxyRelayer = _proxyRelayer;
    }

    function registerProvider(address provider, uint256 initialLiquidity) external onlyOwner {
        approvedProviders[provider] = true;
        providerLiquidity[provider] = initialLiquidity;
        emit ProviderRegistered(provider);
    }

    function updateLiquidity(address provider, uint256 amount) external onlyProxy validProvider(provider) {
        providerLiquidity[provider] = amount;
        emit LiquidityUpdated(provider, amount);
    }

    /// @notice Core monitoring function - validates and logs flash loan requests
    /// @dev Called by the reverse proxy to monitor loan activity
    function monitorAndForward(
        address provider,
        address borrower,
        address token,
        uint256 amount,
        bytes calldata data
    ) external onlyProxy validProvider(provider) nonReentrant returns (bytes32) {

        // Generate unique loan ID
        uint256 nonce = borrowerNonces[borrower];
        bytes32 loanId = _computeLoanId(borrower, token, amount, nonce);

        // Validate loan parameters
        require(amount > 0, "Zero amount");
        require(_validateLoanRatio(provider, amount), "Exceeds max ratio");

        // Record the loan
        loanRecords[loanId] = LoanRecord({
            borrower: borrower,
            token: token,
            amount: amount,
            timestamp: block.timestamp,
            txHash: blockhash(block.number - 1),
            settled: false
        });

        borrowerNonces[borrower] = nonce + 1;
        activeLoans++;
        totalLoansIssued++;

        emit LoanRequested(loanId, borrower, amount);

        // Forward to actual provider
        IFlashLoanProvider(provider).flashLoan(borrower, token, amount, data);

        // Post-execution settlement check
        _settleRecord(loanId, provider, token);

        return loanId;
    }

    /// @notice Batch monitoring for multiple sequential loans
    function batchMonitor(
        address[] calldata providers,
        address borrower,
        address[] calldata tokens,
        uint256[] calldata amounts,
        bytes[] calldata dataPayloads
    ) external onlyProxy nonReentrant returns (bytes32[] memory) {
        require(
            providers.length == tokens.length && 
            tokens.length == amounts.length && 
            amounts.length == dataPayloads.length,
            "Array length mismatch"
        );

        bytes32[] memory loanIds = new bytes32[](providers.length);

        for (uint256 i = 0; i < providers.length; i++) {
            require(approvedProviders[providers[i]], "Provider not approved");

            uint256 nonce = borrowerNonces[borrower];
            bytes32 loanId = _computeLoanId(borrower, tokens[i], amounts[i], nonce);

            // Validate each loan independently
            require(amounts[i] > 0, "Zero amount");
            require(_validateLoanRatio(providers[i], amounts[i]), "Exceeds max ratio");

            loanRecords[loanId] = LoanRecord({
                borrower: borrower,
                token: tokens[i],
                amount: amounts[i],
                timestamp: block.timestamp,
                txHash: blockhash(block.number - 1),
                settled: false
            });

            borrowerNonces[borrower] = nonce + 1;
            activeLoans++;
            totalLoansIssued++;

            emit LoanRequested(loanId, borrower, amounts[i]);

            // Forward to provider
            IFlashLoanProvider(providers[i]).flashLoan(
                borrower, tokens[i], amounts[i], dataPayloads[i]
            );

            loanIds[i] = loanId;
        }

        // Settle all records after batch execution
        for (uint256 i = 0; i < loanIds.length; i++) {
            _settleRecord(loanIds[i], providers[i], tokens[i]);
        }

        return loanIds;
    }

    function _validateLoanRatio(address provider, uint256 amount) internal view returns (bool) {
        uint256 available = providerLiquidity[provider];
        // Check that requested amount doesn't exceed MAX_LOAN_RATIO% of liquidity
        return amount <= (available * MAX_LOAN_RATIO) / 100;
    }

    function _settleRecord(bytes32 loanId, address provider, address token) internal {
        LoanRecord storage record = loanRecords[loanId];

        // Verify the provider still has adequate balance post-loan
        uint256 currentBalance = IERC20(token).balanceOf(provider);

        // Settlement validation: provider balance should be >= recorded liquidity
        // This uses cached providerLiquidity which may be stale from batch operations
        if (currentBalance >= providerLiquidity[provider]) {
            record.settled = true;
            activeLoans--;
            emit LoanSettled(loanId, true);
        } else {
            // Update liquidity to reflect actual state
            providerLiquidity[provider] = currentBalance;
            record.settled = true;
            activeLoans--;
            emit LoanSettled(loanId, false);
        }
    }

    function _computeLoanId(
        address borrower,
        address token,
        uint256 amount,
        uint256 nonce
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(borrower, token, amount, nonce));
    }

    function getLoanRecord(bytes32 loanId) external view returns (LoanRecord memory) {
        return loanRecords[loanId];
    }

    function getActiveLoanCount() external view returns (uint256) {
        return activeLoans;
    }
}
